import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.SerializableTimestampAssigner;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.ConnectedStreams;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileWriter;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    private static final Duration OUT_OF_ORDER = Duration.ofMinutes(1);

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssizeSeconds = params.getInt("sesssize", 600);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        WatermarkStrategy<TaskEvent> taskWms = WatermarkStrategy
                .<TaskEvent>forBoundedOutOfOrderness(OUT_OF_ORDER)
                .withTimestampAssigner((SerializableTimestampAssigner<TaskEvent>) (event, recordTimestamp) -> event.timestamp / 1000L);

        WatermarkStrategy<JobEvent> jobWms = WatermarkStrategy
                .<JobEvent>forBoundedOutOfOrderness(OUT_OF_ORDER)
                .withTimestampAssigner((SerializableTimestampAssigner<JobEvent>) (event, recordTimestamp) -> event.timestamp / 1000L);

        DataStream<TaskEvent> taskEvents = env
                .addSource(taskSourceOrTest(new GzippedTaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(taskWms);

        DataStream<JobEvent> jobEvents = env
                .addSource(jobSourceOrTest(new GzippedJobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(jobWms);

        DataStream<JobSessionCount> sessionCounts = taskEvents
                .filter(e -> e.eventType == TaskEvent.SUBMIT && e.jobId >= 0)
                .keyBy(e -> e.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssizeSeconds)))
                .aggregate(new CountAgg(), new AddWindowInfo());

        DataStream<JobEvent> terminalJobs = jobEvents
                .filter(e -> e.jobId >= 0 && e.isTerminal());

        ConnectedStreams<JobSessionCount, JobEvent> connected = sessionCounts
                .keyBy(sc -> sc.jobId)
                .connect(terminalJobs.keyBy(j -> j.jobId));

        long finalizeDelayMillis = (long) sesssizeSeconds * 1000L + OUT_OF_ORDER.toMillis();

        DataStream<String> result = connected
                .process(new EmitOnJobFinish(finalizeDelayMillis))
                .map((MapFunction<Tuple2<Long, Long>, String>) t -> "(" + t.f0 + "," + t.f1 + ")");

        if (outputPath != null) {
            result.addSink((org.apache.flink.streaming.api.functions.sink.SinkFunction<String>) sinkOrTest(new LocalTextFileSink(outputPath)));
        } else {
            result.addSink((org.apache.flink.streaming.api.functions.sink.SinkFunction<String>) sinkOrTest(new RichSinkFunction<String>() {
                @Override
                public void invoke(String value, Context context) {
                    System.out.println(value);
                }
            }));
        }

        env.execute("LongestSessionPerJob");
    }

    private static class JobSessionCount {
        public long jobId;
        public long count;
        public long windowEndMillis;

        public JobSessionCount() {
        }

        public JobSessionCount(long jobId, long count, long windowEndMillis) {
            this.jobId = jobId;
            this.count = count;
            this.windowEndMillis = windowEndMillis;
        }
    }

    private static class CountAgg implements AggregateFunction<TaskEvent, Long, Long> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            return accumulator + 1L;
        }

        @Override
        public Long getResult(Long accumulator) {
            return accumulator;
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    private static class AddWindowInfo extends ProcessWindowFunction<Long, JobSessionCount, Long, TimeWindow> {
        @Override
        public void process(Long key, Context context, Iterable<Long> elements, Collector<JobSessionCount> out) {
            long count = elements.iterator().next();
            out.collect(new JobSessionCount(key, count, context.window().getEnd()));
        }
    }

    private static class EmitOnJobFinish extends KeyedCoProcessFunction<Long, JobSessionCount, JobEvent, Tuple2<Long, Long>> {
        private final long finalizeDelayMillis;

        private transient ValueState<Long> maxStage;
        private transient ValueState<Boolean> finished;
        private transient ValueState<Long> finishTimer;

        private EmitOnJobFinish(long finalizeDelayMillis) {
            this.finalizeDelayMillis = finalizeDelayMillis;
        }

        @Override
        public void open(Configuration parameters) {
            maxStage = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStage", Long.class));
            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
            finishTimer = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTimer", Long.class));
        }

        @Override
        public void processElement1(JobSessionCount value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Long current = maxStage.value();
            if (current == null || value.count > current) {
                maxStage.update(value.count);
            }
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Boolean isFinished = finished.value();
            if (isFinished != null && isFinished) {
                return;
            }

            finished.update(true);

            long timerTs = (value.timestamp / 1000L) + finalizeDelayMillis;
            Long existing = finishTimer.value();
            if (existing == null || timerTs > existing) {
                if (existing != null) {
                    ctx.timerService().deleteEventTimeTimer(existing);
                }
                finishTimer.update(timerTs);
                ctx.timerService().registerEventTimeTimer(timerTs);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            Boolean isFinished = finished.value();
            if (isFinished == null || !isFinished) {
                return;
            }

            Long max = maxStage.value();
            out.collect(Tuple2.of(ctx.getCurrentKey(), max == null ? 0L : max));

            maxStage.clear();
            finished.clear();
            finishTimer.clear();
        }
    }

    private static class LocalTextFileSink extends RichSinkFunction<String> {
        private final String path;
        private transient BufferedWriter writer;

        private LocalTextFileSink(String path) {
            this.path = path;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            File f = new File(path);
            File parent = f.getParentFile();
            if (parent != null) {
                parent.mkdirs();
            }
            writer = new BufferedWriter(new FileWriter(f, false));
        }

        @Override
        public void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.flush();
                writer.close();
            }
        }
    }

    private static class GzippedTaskEventSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        private GzippedTaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(new GZIPInputStream(new FileInputStream(path)), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    try {
                        ctx.collect(TaskEvent.fromCsv(line));
                    } catch (RuntimeException ignored) {
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static class GzippedJobEventSource implements SourceFunction<JobEvent> {
        private final String path;
        private volatile boolean running = true;

        private GzippedJobEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(new GZIPInputStream(new FileInputStream(path)), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    try {
                        ctx.collect(JobEvent.fromCsv(line));
                    } catch (RuntimeException ignored) {
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }
}
