import java.io.Serializable;

public class JobEvent implements Serializable {
    public static final int FINISH = 4;
    public static final int KILL = 5;

    public long timestamp;
    public long jobId;
    public int eventType;

    public JobEvent() {
    }

    public JobEvent(long timestamp, long jobId, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.eventType = eventType;
    }

    public boolean isTerminal() {
        return eventType == FINISH || eventType == KILL;
    }

    public static JobEvent fromCsv(String line) {
        String[] parts = line.split(",", -1);
        long timestamp = parseLong(parts, 0);
        long jobId = parseLong(parts, 2);
        int eventType = parseInt(parts, 3);
        return new JobEvent(timestamp, jobId, eventType);
    }

    private static long parseLong(String[] parts, int idx) {
        if (idx >= parts.length || parts[idx].isEmpty()) {
            return -1L;
        }
        return Long.parseLong(parts[idx]);
    }

    private static int parseInt(String[] parts, int idx) {
        if (idx >= parts.length || parts[idx].isEmpty()) {
            return -1;
        }
        return Integer.parseInt(parts[idx]);
    }
}
